<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';
require_once __DIR__.'/../../config/db.php';
require_once __DIR__.'/../../includes/report_tools.php';

$from=trim((string)($_GET['from']??date('Y-m-01')));
$to=trim((string)($_GET['to']??date('Y-m-d')));
$valid='/^\\d{4}-\\d{2}-\\d{2}$/';
if(!preg_match($valid,$from))$from=date('Y-m-01');
if(!preg_match($valid,$to))$to=date('Y-m-d');
if($from>$to){[$from,$to]=[$to,$from];}
$search=trim((string)($_GET['q']??''));
$method=trim((string)($_GET['method']??''));
$where=['DATE(sp.payment_date) BETWEEN ? AND ?'];$params=[$from,$to];
if($search!==''){$where[]='(s.supplier_name LIKE ? OR sp.receipt_number LIKE ? OR sp.transaction_reference LIKE ?)';$like='%'.$search.'%';array_push($params,$like,$like,$like);}
if(in_array($method,['Cash','M-Pesa','Bank','Cheque','Other'],true)){$where[]='sp.payment_method=?';$params[]=$method;}
$recentQ=$conn->prepare("SELECT sp.*,s.supplier_name,u.full_name FROM supplier_payments sp JOIN suppliers s ON s.id=sp.supplier_id LEFT JOIN users u ON u.id=sp.user_id WHERE ".implode(' AND ',$where)." ORDER BY sp.payment_date DESC,sp.id DESC");
$recentQ->execute($params);$recent=$recentQ->fetchAll(PDO::FETCH_ASSOC);
$suppliers=$conn->query("SELECT id,supplier_name,balance FROM suppliers WHERE status='Active' ORDER BY supplier_name")->fetchAll();
$periodTotal=0.0;$exportRows=[];foreach($recent as $p){$periodTotal+=(float)$p['amount'];$exportRows[]=[$p['receipt_number'],$p['payment_date'],$p['supplier_name'],$p['amount'],$p['payment_method'],$p['transaction_reference']??'',$p['full_name']??''];}
dibonkeReportExport('supplier_payments_'.$from.'_to_'.$to,['Receipt','Date','Supplier','Amount','Method','Reference','Paid By'],$exportRows);
$flash=$_SESSION['supplier_payment_flash']??null;unset($_SESSION['supplier_payment_flash']);
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?>
<main class="content"><?php dibonkeReportPrintStyles(); ?><h1>Supplier Payments</h1><p>Settle supplier payables and maintain the supplier ledger.</p><?php if($flash):?><div class="flash"><?=e($flash)?></div><?php endif;?>
<div class="grid"><div class="panel"><h3>Make Payment</h3><form method="post" action="store.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Supplier<select name="supplier_id" required><option value="">Select supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['supplier_name'])?> — KES <?=number_format((float)$s['balance'],2)?></option><?php endforeach;?></select></label><label>Amount<input type="number" name="amount" min=".01" step=".01" required></label><label>Payment Method<select name="payment_method" id="sp_method"><option>Cash</option><option>Bank</option><option>Cheque</option><option>Other</option></select></label><label>Transaction Reference<input name="transaction_reference" placeholder="Required for M-PESA"></label><label>Notes<input name="notes"></label><button class="btn">Record Supplier Payment</button></form></div>
<div class="panel"><h3>Payment History <small>(KES <?=number_format($periodTotal,2)?> filtered)</small></h3><form class="filter" method="get"><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><label>Method<select name="method"><option value="">All methods</option><?php foreach(['Cash','M-Pesa','Bank','Cheque','Other'] as $m):?><option value="<?=e($m)?>" <?=$method===$m?'selected':''?>><?=e($m)?></option><?php endforeach;?></select></label><label>Search<input name="q" value="<?=e($search)?>" placeholder="Supplier, receipt, reference..."></label><button>Filter</button></form><?php dibonkeReportActions('supplier_payments'); ?><div class="scroll"><table><thead><tr><th>Receipt</th><th>Date</th><th>Supplier</th><th>Amount</th><th>Method</th><th>Reference</th><th>Paid By</th></tr></thead><tbody><?php foreach($recent as $p):?><tr><td><?=e($p['receipt_number'])?></td><td><?=e($p['payment_date'])?></td><td><?=e($p['supplier_name'])?></td><td>KES <?=number_format((float)$p['amount'],2)?></td><td><?=e($p['payment_method'])?></td><td><?=e($p['transaction_reference']??'')?></td><td><?=e($p['full_name']??'—')?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="7">No supplier payments match these filters.</td></tr><?php endif;?></tbody></table></div></div></div></main>
<style>.grid{display:grid;grid-template-columns:360px minmax(0,1fr);gap:18px}.panel{background:#fff;padding:20px;border-radius:12px;box-shadow:0 1px 5px #0001;min-width:0}.panel label{display:block;font-size:12px;font-weight:700;margin:12px 0}.panel input,.panel select{display:block;width:100%;box-sizing:border-box;padding:10px;margin-top:5px;border:1px solid #dbe3ec;border-radius:7px}.btn{padding:11px 15px;border:0;border-radius:7px;background:#004a99;color:#fff;font-weight:700;width:100%}.flash{padding:12px;background:#ecfdf5;color:#166534;border-radius:8px;margin-bottom:15px}.scroll{overflow:auto}.filter{display:grid;grid-template-columns:repeat(4,minmax(110px,1fr));gap:9px;align-items:end;margin:12px 0}.filter label{font-size:11px;font-weight:700}.filter label input,.filter label select{display:block;margin-top:5px}.filter button{padding:10px;border:0;border-radius:7px;background:#174a7e;color:#fff;font-weight:700}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #e5e7eb;text-align:left;font-size:13px}th{background:#004a99;color:#fff}@media(max-width:1000px){.grid{grid-template-columns:1fr}}@media(max-width:700px){.filter{grid-template-columns:1fr 1fr}}</style><?php require_once __DIR__.'/../../includes/footer.php';?>